RIDES = [('Polar X-plorer', 'family coaster'), ('Ninjago The Ride', 'dark ride'), ('The Dragon', 'family coaster'), ('Flying Eagle', 'family coaster')]
print('Ride-type classifier: Legoland Billund')
counts = {}
for name, kind in RIDES:
    counts[kind] = counts.get(kind, 0) + 1
for kind in sorted(counts):
    print("%s: %d" % (kind, counts[kind]))
print("Operating rides classified: %d" % len(RIDES))

